<?php
declare(strict_types=1);require __DIR__.'/_bootstrap.php';
if(!in_array(strtolower((string)($currentUser['role']??'')),['superadmin','admin','manager','organiser'],true)){header('Location:index.php');exit;}
$sectionId=max(0,(int)($_GET['section_id']??$_POST['section_id']??0));$newsId=max(0,(int)($_GET['news_id']??$_POST['news_id']??0));$section=$sectionId?fetchNewsSection($pdo,$sectionId):null;if($section){$newsId=(int)$section['news_id'];}$news=fetchNewsArticle($pdo,$newsId);if(!$news){header('Location:news.php');exit;}$kind=$section?'news_section_images':'news_images';$ownerType=$section?'news_content_section':'news_article';$ownerId=$section?(int)$section['id']:$newsId;$batch=mediaBatchGetOrCreate($pdo,$kind,$ownerType,$ownerId,'Images for '.($section['subheading']??$news['headline']),'news');
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'upload';if($action==='upload'){$errors=[];$count=mediaBatchUpload($pdo,$batch,$_FILES['images']??[],['original'=>null,'lg'=>1200,'md'=>600,'sm'=>300,'xs'=>150],$errors);foreach($errors as$error)$alerts[]=['type'=>'danger','message'=>$error];if($count){$_SESSION['flash_success']=$count.($count===1?' image':' images').' uploaded.';header('Location:news_images.php?'.($section?'section_id='.$sectionId:'news_id='.$newsId));exit;}}else{foreach(array_column(mediaBatchImages($pdo,(int)$batch['id'],true),null,'id') as$imageId=>$image){$v=$_POST['image'][$imageId]??null;if(!$v)continue;$pdo->prepare('UPDATE media_batch_images SET title=:title,alt_text=:alt,caption=:caption,display_order=:ord,lightbox_enabled=:lightbox,archived=:archived WHERE id=:id AND batch_id=:batch')->execute([':title'=>trim((string)($v['title']??''))?:null,':alt'=>trim((string)($v['alt_text']??''))?:null,':caption'=>trim((string)($v['caption']??''))?:null,':ord'=>(int)($v['display_order']??100),':lightbox'=>!empty($v['lightbox_enabled'])?1:0,':archived'=>!empty($v['archived'])?1:0,':id'=>$imageId,':batch'=>$batch['id']]);}$_SESSION['flash_success']='Gallery details updated.';header('Location:news_images.php?'.($section?'section_id='.$sectionId:'news_id='.$newsId));exit;}}
$images=mediaBatchImages($pdo,(int)$batch['id'],true);admin_layout_start('News Gallery','news');?>
<div class="d-flex justify-content-between mb-3"><h5><?php echo h($section['subheading']??$news['headline']); ?> — Gallery</h5><a class="btn btn-outline-secondary" href="<?php echo $section?'news_sections.php?news_id='.$newsId:'news_edit.php?id='.$newsId; ?>">Back</a></div><div class="card-soft p-4 mb-4"><h6>Upload images</h6><form method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="upload"><input type="hidden" name="news_id" value="<?php echo $newsId; ?>"><input type="hidden" name="section_id" value="<?php echo $sectionId; ?>"><label id="news-drop-zone" class="d-block border border-2 border-secondary-subtle rounded-3 p-4 text-center bg-light" style="cursor:pointer;transition:border-color .15s,background-color .15s"><input class="visually-hidden" id="news-images" type="file" name="images[]" accept="image/jpeg,image/png,image/gif,image/webp" multiple required><span class="d-block fs-5 fw-semibold">Drop images here</span><span class="d-block text-muted">or click to select multiple images</span><span id="news-file-summary" class="d-block small mt-2 text-success"></span></label><div class="form-text">You can add titles, alternative text, captions and display order after upload.</div><button class="btn btn-success mt-3">Upload Images</button></form></div><div class="card-soft p-3"><form method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="news_id" value="<?php echo $newsId; ?>"><input type="hidden" name="section_id" value="<?php echo $sectionId; ?>"><div class="table-responsive"><table class="table align-middle" data-admin-inline-reorder><thead><tr><th>Preview</th><th style="width:90px">Order</th><th>Title / alternative text / caption</th><th>Options</th></tr></thead><tbody><?php foreach($images as$i=>$image): ?><tr data-order-id="<?php echo (int)$image['id']; ?>"><td><img src="<?php echo h(mediaBatchImageUrl($batch,$image,'sm')); ?>" style="width:180px;max-height:100px;object-fit:cover" class="rounded"></td><td><input class="form-control" data-display-order type="number" name="image[<?php echo $image['id']; ?>][display_order]" value="<?php echo $image['display_order']; ?>"></td><td><input class="form-control form-control-sm mb-1" name="image[<?php echo $image['id']; ?>][title]" value="<?php echo h($image['title']??''); ?>" placeholder="Title"><input class="form-control form-control-sm mb-1" name="image[<?php echo $image['id']; ?>][alt_text]" value="<?php echo h($image['alt_text']??''); ?>" placeholder="Alternative text"><textarea class="form-control form-control-sm" rows="2" name="image[<?php echo $image['id']; ?>][caption]" placeholder="Caption"><?php echo h($image['caption']??''); ?></textarea></td><td><label class="d-block mb-2"><input type="checkbox" name="image[<?php echo $image['id']; ?>][lightbox_enabled]" value="1" <?php echo !array_key_exists('lightbox_enabled',$image)||!empty($image['lightbox_enabled'])?'checked':''; ?>> Lightbox</label><label><input type="checkbox" name="image[<?php echo $image['id']; ?>][archived]" value="1" <?php echo !empty($image['archived'])?'checked':''; ?>> Archived</label></td></tr><?php endforeach; ?><?php if(!$images): ?><tr><td colspan="4" class="text-muted">No gallery images yet.</td></tr><?php endif; ?></tbody></table></div><?php if($images): ?><button class="btn btn-success">Save Gallery</button><?php endif; ?></form></div><script>(function(){const z=document.getElementById('news-drop-zone'),i=document.getElementById('news-images'),s=document.getElementById('news-file-summary');function show(){const files=Array.from(i.files||[]);s.textContent=files.length?files.length+(files.length===1?' image selected: ':' images selected: ')+files.map(file=>file.name).join(', '):'';}['dragenter','dragover'].forEach(type=>z.addEventListener(type,event=>{event.preventDefault();z.classList.add('border-success','bg-success-subtle');}));['dragleave','drop'].forEach(type=>z.addEventListener(type,event=>{event.preventDefault();z.classList.remove('border-success','bg-success-subtle');}));z.addEventListener('drop',event=>{if(event.dataTransfer&&event.dataTransfer.files.length){i.files=event.dataTransfer.files;show();}});i.addEventListener('change',show);})();</script><?php admin_layout_end();
